function generate_digest(reg_type, val_64bit):
    if reg_type == INT:
        // Count trailing and leading identical bits (zeros or ones)
        trailing_cnt = count_trailing_zeros_or_ones(val_64bit) & 0x3F  // 6 bits
        leading_cnt = count_leading_zeros_or_ones(val_64bit) & 0x3F    // 6 bits
        lsb6 = val_64bit & 0x3F                                       // 6 bits
        // Overlapping XOR-fold into 12 bits
        digest = trailing_cnt ^ (leading_cnt << 3) ^ (lsb6 << 6)
        return digest & 0x0FFF
    elif reg_type == FP:
        // Inspect MSBs to classify FP format (assumed standard IEEE-754 sizes)
        if is_fp16:
            // Val[15:13]: sign bit and top 2 exponent bits placed at [5:3]
            return ((val_64bit >> 13) & 0x7) << 3
        elif is_fp32:
            // Val[31:26]: sign bit and top 5 exponent bits placed at [8:3]
            return ((val_64bit >> 26) & 0x3F) << 3
        else: // FP64
            // Val[63:55]: sign bit and top 8 exponent bits placed at [11:3]
            return ((val_64bit >> 55) & 0x1FF) << 3
    elif reg_type == FLAG:
        // 4 flag bits replicated 3 times to fill 12 bits
        f = val_64bit & 0x0F
        return f | (f << 4) | (f << 8)
    else:
        return 0

function on_decode(dest_reg, rob_tag):
    if dest_reg >= 0 and dest_reg < 65:
        reg_table[dest_reg].valid = 0
        reg_table[dest_reg].payload = rob_tag & 0x3FFF  // 14-bit ROB tag
        reg_table[dest_reg].decay_ctr = 0

function on_complete(dest_reg, rob_tag, reg_value, reg_type):
    if dest_reg >= 0 and dest_reg < 65:
        // Verify completing instruction matches current occupant
        if reg_table[dest_reg].valid == 0 and reg_table[dest_reg].payload == (rob_tag & 0x3FFF):
            digest = generate_digest(reg_type, reg_value)
            reg_table[dest_reg].payload = digest & 0x0FFF  // 12-bit digest
            reg_table[dest_reg].valid = 1
            reg_table[dest_reg].decay_ctr = 0

