function predict_sR(branch_pc):
    sR_sum = 0
    for b = 0 to 7:
        bank_valid_regs = []
        for r in registers_of_bank(b): // R[b + 8*k]
            if reg_table[r].valid == 1:
                bank_valid_regs.append(r)

        if bank_valid_regs is empty:
            continue // Bank contribution is 0 (x0)

        // Query UT0, UT1, UT2 for this bank
        idx0 = hash_ut(branch_pc, 0, b)
        idx1 = hash_ut(branch_pc, 1, b)
        idx2 = hash_ut(branch_pc, 2, b)

        best_reg = NULL
        max_useful = -9999
        for r in bank_valid_regs:
            sub_idx = register_index_in_bank(r, b)
            u = UT[b][0][idx0][sub_idx] + UT[b][1][idx1][sub_idx] + UT[b][2][idx2][sub_idx]
            if u > max_useful:
                max_useful = u
                best_reg = r

        // Record chosen register and bank availability for training update
        pred_snapshot.bank_valid_regs[b] = bank_valid_regs
        pred_snapshot.selected_reg[b] = best_reg
        pred_snapshot.max_useful[b] = max_useful

        // Select digest and compute bank WT contribution
        if max_useful > 0:
            digest = reg_table[best_reg].payload & 0x0FFF
            h0 = hash_wt(branch_pc, digest, 0) % 512
            h1 = hash_wt(branch_pc, digest, 1) % 256
            h2 = hash_wt(branch_pc, digest, 2) % 128

            w_sum = WT[b][0][h0] + WT[b][1][h1] + WT[b][2][h2]
            bank_contrib = floor(w_sum * 2.5)
            sR_sum += bank_contrib
        else:
            // Non-useful bank contribution suppressed (x0)
            pass

    return sR_sum

